const a=e=>{switch(e.length){case 10:return"Desa/Kelurahan";case 7:return"Kecamatan";case 4:return e.substring(2,3)=="7"?"Kota":"Kabupaten";case 2:return"Provinsi";default:return"-"}},r=e=>{switch(e.length){case 10:return"Kepala Desa/Kelurahan";case 7:return"Camat";case 4:return e.substring(2,3)=="7"?"Walikota":"Bupati";case 2:return"Gubernur";default:return"-"}};export{r as a,a as l};
